"""Deployable reachability: answers generated by one edit of a linked neighbour's *predicted* top-k structures."""
import sys, numpy as np, pandas as pd
sys.path.insert(0, '/Users/b/casmi26/fp'); sys.path.insert(0, '/Users/b/casmi26-repo/bench/obscure_np')
from edits import edit_products
from common import scorer_key
from rdkit import Chem
from rdkit.Chem.Descriptors import ExactMolWt
s, run, k, th = sys.argv[1], sys.argv[2], int(sys.argv[3]), float(sys.argv[4])
sol = pd.read_csv(f'{s}/solution.csv').set_index('molecule_id')
sub = {m: [x for x in str(v).split(';') if x and x != 'CCO'] for m, v in pd.read_csv(run).values}
P = pd.read_parquet(f'{s}/pairs.parquet'); P = P[P.modcos >= th]
mass = {m: ExactMolWt(Chem.MolFromSmiles(x)) for m, x in sol.smiles.items()}
tkey = {m: scorer_key(x) for m, x in sol.smiles.items()}
nb = {}
for a, b in zip(P.a, P.b):
    nb.setdefault(a, set()).add(b); nb.setdefault(b, set()).add(a)
for cls in (3, 2):
    ids = sol[sol.cls == cls].index; hit, sizes, seedok, already = 0, [], 0, 0
    for x in ids:
        cands = {}
        for y in nb.get(x, ()):
            for seed in sub.get(y, [])[:k]:
                for smi in edit_products(seed):
                    mm = Chem.MolFromSmiles(smi)
                    if mm is not None and abs(ExactMolWt(mm) - mass[x]) < mass[x] * 1e-5:
                        cands[smi] = 1
        keys = {scorer_key(c) for c in cands} - {None}
        sizes.append(len(keys))
        own = {scorer_key(c) for c in sub.get(x, [])[:25]}
        if tkey[x] in keys:
            hit += 1
            already += tkey[x] in own
    print(f'{s} cls{cls} n {len(ids)}: answer in edits of neighbours\' top-{k}: {hit} ({hit / len(ids):.1%}), '
          f'of which already in own top 25: {already} | generated per molecule median {np.median(sizes):.0f} mean {np.mean(sizes):.0f}')
